    const profileStorageKey='fridge-profile-v1';
    function readProfile(){try{const p=JSON.parse(localStorage.getItem(profileStorageKey)||'{}');return {name:typeof p.name==='string'?p.name.slice(0,20):'',height:Number(p.height)>0?Number(p.height):0,weight:Number(p.weight)>0?Number(p.weight):0,age:Number(p.age)>0?Number(p.age):0,gender:p.gender==='female'?'female':'male',activity:Number(p.activity)>0?Number(p.activity):1.55,goal:p.goal==='cut'?'cut':p.goal==='bulk'?'bulk':'maintain'}}catch{return {name:'',height:0,weight:0,age:0,gender:'male',activity:1.55,goal:'maintain'}}}
    function saveProfile(p){localStorage.setItem(profileStorageKey,JSON.stringify(p));window.FridgeCloudSync?.localChanged('profile')}
    function exportBackup(){
      const backup={app:'fridge-manager',version:2,exportedAt:new Date().toISOString(),profile:readProfile(),inventory,customFoods:customFoodRecords,menuPurchase:readMenuPurchase(),dietLogs:readDietLogs(),barcodeFoods:readBarcodeFoodNames(),shareReservations:readShareReservations()};
      const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
      a.href=url;a.download=`冰箱数据备份-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出');
    }
    function importBackup(file){
      const reader=new FileReader();
      reader.onload=()=>{
        try{
          const d=JSON.parse(reader.result);
          if(!d||d.app!=='fridge-manager'||![1,2].includes(Number(d.version))||!Array.isArray(d.inventory))throw new Error('bad');
          const items=d.inventory.map(x=>{
            if(!x||typeof x.name!=='string'||!x.name.trim()||!Number.isFinite(Number(x.weight))||Number(x.weight)<=0)throw new Error('inventory');
            const expiry=Number(x.expiry),added=Number(x.added);
            if(!Number.isFinite(expiry)||!Number.isFinite(added))throw new Error('inventory');
            return {name:x.name.trim(),weight:Number(x.weight),unit:['piece','ml'].includes(x.unit)?x.unit:'g',expiry,added};
          });
          const values=new Map([['fridge-foods-v2',JSON.stringify(items)]]);
          if(d.customFoods!==undefined){
            if(!Array.isArray(d.customFoods)||d.customFoods.some(food=>!food||!isValidCustomFoodName(food.name)||!customFoodCategories.includes(food.category)||!Number.isFinite(Number(food.kcal))||Number(food.kcal)<0))throw new Error('custom foods');
            values.set(customFoodStorageKey,JSON.stringify(d.customFoods));
          }
          if(d.menuPurchase)values.set(menuPurchaseKey,JSON.stringify(d.menuPurchase));else values.set(menuPurchaseKey,null);
          if(d.profile&&typeof d.profile==='object')values.set(profileStorageKey,JSON.stringify(d.profile));
          if(d.dietLogs!==undefined){
            if(!d.dietLogs||typeof d.dietLogs!=='object'||Array.isArray(d.dietLogs)||Object.entries(d.dietLogs).some(([date,day])=>!/^\d{4}-\d{2}-\d{2}$/.test(date)||!day||!Array.isArray(day.meals)||day.meals.some(meal=>!meal||typeof meal.name!=='string'||!['kcal','carbs','protein','fat'].every(key=>Number.isFinite(Number(meal[key]))))))throw new Error('diet logs');
            values.set(dietLogKey,JSON.stringify(d.dietLogs));
          }
          if(d.barcodeFoods!==undefined){
            if(!d.barcodeFoods||typeof d.barcodeFoods!=='object'||Array.isArray(d.barcodeFoods)||Object.entries(d.barcodeFoods).some(([code,name])=>!/^\d{8,14}$/.test(code)||typeof name!=='string'||!name.trim()))throw new Error('barcode foods');
            values.set(barcodeFoodStorageKey,JSON.stringify(d.barcodeFoods));
          }
          if(d.shareReservations!==undefined){
            if(!Array.isArray(d.shareReservations)||d.shareReservations.some(row=>!row||typeof row.id!=='string'||!row.item||typeof row.item.name!=='string'||!Number.isFinite(Number(row.weight))||Number(row.weight)<=0||!Number.isFinite(Number(row.item.added))||!Number.isFinite(Number(row.item.expiry))))throw new Error('share reservations');
            values.set(shareReservationsStorageKey,JSON.stringify(d.shareReservations));
          }else values.set(shareReservationsStorageKey,JSON.stringify([]));
          const previous=new Map([...values.keys()].map(key=>[key,localStorage.getItem(key)]));
          try{for(const [key,value] of values){if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value)}}
          catch(error){for(const [key,value] of previous){if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value)}throw error}
          toast('导入成功，正在刷新');setTimeout(()=>location.reload(),600);
        }catch(e){toast('导入失败：文件格式不正确或存储空间不足')}
      };
      reader.onerror=()=>toast('读取备份文件失败');reader.readAsText(file);
    }

    const categoryMacros={'肉类':{carbs:0,protein:20,fat:12},'鱼类':{carbs:0,protein:20,fat:5},'海鲜':{carbs:1,protein:18,fat:2},'蛋奶':{carbs:5,protein:10,fat:8},'蔬菜':{carbs:5,protein:2,fat:0.3},'水果':{carbs:12,protein:0.6,fat:0.3},'主食':{carbs:25,protein:4,fat:1},'豆制品':{carbs:4,protein:8,fat:4},'豆类':{carbs:20,protein:9,fat:1},'调味品':{carbs:10,protein:1,fat:8},'坚果':{carbs:16,protein:18,fat:50},'乳制品':{carbs:5,protein:6,fat:10},'其他':{carbs:10,protein:5,fat:5}};
    function getFoodMacros(name){return categoryMacros[getFood(name).category]||categoryMacros['其他']}
    function recipeMacros(recipe,mult=1){let carbs=0,protein=0,fat=0;recipe.ingredients.forEach(([name,grams])=>{const m=getFoodMacros(name),g=grams*mult/100;carbs+=m.carbs*g;protein+=m.protein*g;fat+=m.fat*g});(recipeSeasonings[recipe.id]||[]).forEach(([name,grams])=>{if(name.includes('油'))fat+=grams*mult/100});return {carbs:Math.round(carbs),protein:Math.round(protein),fat:Math.round(fat)}}
    const dietTargets={kcal:2000,carbs:250,protein:75,fat:65};
    function calcTargets(p){const w=Number(p.weight);if(!w||w<=0)return dietTargets;const h=Number(p.height),age=Number(p.age),act=Number(p.activity)||1.55,goal=p.goal||'maintain';let bmr;if(h>0&&age>0){bmr=p.gender==='female'?10*w+6.25*h-5*age-161:10*w+6.25*h-5*age+5}else{bmr=22*w}const kcal=Math.max(1200,Math.round(bmr*act*(goal==='cut'?0.8:goal==='bulk'?1.1:1))),protein=Math.max(50,Math.round(w*(goal==='maintain'?1.4:1.8))),fat=Math.max(35,Math.round(kcal*0.25/9)),carbs=Math.max(100,Math.round((kcal-protein*4-fat*9)/4));return {kcal,carbs,protein,fat}}
    function getDietTargets(){return calcTargets(readProfile())}
    function updateProfileInfo(){const p={height:Number($('profile-height').value),weight:Number($('profile-weight').value),age:Number($('profile-age').value),gender:$('profile-gender').value,activity:Number($('profile-activity').value),goal:$('profile-goal').value};let txt='';if(p.height>0&&p.weight>0){const bmi=p.weight/((p.height/100)*(p.height/100)),cat=bmi<18.5?'偏瘦':bmi<24?'正常':bmi<28?'超重':'肥胖',t=calcTargets(p);txt=`BMI ${bmi.toFixed(1)}（${cat}） · 每日约 ${t.kcal} 千卡 · 碳水 ${t.carbs}g · 蛋白 ${t.protein}g · 脂肪 ${t.fat}g`}else{txt='填写身高体重后，自动计算 BMI 和每日营养目标。'}$('profile-bmi').innerHTML=`<p class="helper">${txt}</p>`}

    const dietLogKey='fridge-diet-log-v2';
    function todayStr(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
    function readDietLogs(){try{const l=JSON.parse(localStorage.getItem(dietLogKey)||'{}');return (l&&typeof l==='object'&&!Array.isArray(l))?l:{}}catch{return {}}}
    function saveDietLogs(logs){Object.values(logs).forEach(day=>(day.meals||[]).forEach(meal=>{if(!meal.recordId)meal.recordId=createLocalId()}));localStorage.setItem(dietLogKey,JSON.stringify(logs));window.FridgeCloudSync?.localChanged('diet_meals')}
    function dietLogFor(date){const logs=readDietLogs();return {date,meals:(logs[date]||{}).meals||[]}}
    function recordMeal(recipe,mult){const logs=readDietLogs(),d=todayStr(),day=logs[d]||{meals:[]},m=recipeMacros(recipe,mult);day.meals.push({recordId:createLocalId(),id:recipe.id,name:recipe.name,emoji:recipe.emoji,kcal:recipeTotalKcal(recipe,mult),carbs:m.carbs,protein:m.protein,fat:m.fat,at:Date.now()});logs[d]=day;saveDietLogs(logs)}
    function dietTotals(log){return log.meals.reduce((a,m)=>({kcal:a.kcal+(m.kcal||0),carbs:a.carbs+(m.carbs||0),protein:a.protein+(m.protein||0),fat:a.fat+(m.fat||0)}),{kcal:0,carbs:0,protein:0,fat:0})}
    function macroRing(label,have,target,color){const pct=Math.min(1,Math.max(0,target>0?have/target:0)),r=42,C=2*Math.PI*r,offset=C*(1-pct),gap=target-have,status=gap>0?`还差 ${Math.round(gap)} 克`:(gap<0?`超出 ${Math.round(-gap)} 克`:'已达标'),sc=gap>0?'#c07b3a':(gap<0?'#c07b3a':'var(--green)');return `<div style="text-align:center;min-width:0"><div style="position:relative;width:78px;height:78px;margin:0 auto"><svg width="78" height="78" viewBox="0 0 100 100"><circle cx="50" cy="50" r="42" fill="none" stroke="#e6f0e6" stroke-width="9"/><circle cx="50" cy="50" r="42" fill="none" stroke="${color}" stroke-width="9" stroke-linecap="round" stroke-dasharray="${C}" stroke-dashoffset="${offset}" transform="rotate(-90 50 50)"/></svg><div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1.25"><b style="font-size:15px">${Math.round(have)}</b><span style="font-size:10px;color:var(--muted)">/ ${Math.round(target)}克</span></div></div><div style="font-size:12px;margin-top:6px;font-weight:650">${label}</div><div style="font-size:10px;margin-top:2px;color:${sc}">${status}</div></div>`}
    function dietAdvice(log){const t=getDietTargets(),total=dietTotals(log),gaps=[['碳水','carbs'],['蛋白质','protein'],['脂肪','fat']].filter(([label,key])=>t[key]-total[key]>5).map(([label,key])=>({label,key,need:t[key]-total[key]})),logged=new Set(log.meals.map(m=>m.id));if(!gaps.length)return '<p class="helper">今日营养摄入基本达标，继续保持均衡饮食。</p>';const recs=[];gaps.forEach(g=>{recipes.filter(r=>!logged.has(r.id)).map(r=>({r,v:recipeMacros(r,1)[g.key]})).sort((a,b)=>b.v-a.v).slice(0,2).forEach(x=>{if(!recs.some(y=>y.id===x.r.id))recs.push({id:x.r.id,name:x.r.name,emoji:x.r.emoji})})});return `<p class="helper">${gaps.map(g=>`${g.label}还差约 ${Math.round(g.need)} 克`).join('、')}，可优先考虑：</p>${recs.slice(0,4).map(x=>`<button type="button" class="subchip" data-advice-recipe="${x.id}">${x.emoji} ${x.name}</button>`).join('')}`}
    function renderAchievements(){const logs=readDietLogs(),days=Object.values(logs).filter(day=>Array.isArray(day?.meals)&&day.meals.length>0).length,meals=Object.values(logs).reduce((sum,day)=>sum+(Array.isArray(day?.meals)?day.meals.length:0),0),foodTypes=new Set(inventory.map(item=>item.name)).size,shareCount=nearbyShareCount,rankNames=['木制','铁质','铜质','白银','铂金','黄金','钻石','大师'],rankColors=[['#ad8050','#80562f'],['#b9c1c7','#7c878e'],['#c98754','#92582f'],['#d7e0e8','#8294a3'],['#8ad8d4','#378e91'],['#f5ca50','#bd8125'],['#b6a4f7','#7056bd'],['#ff8ec5','#bd387c']];const achievements=[{icon:'🥄',name:'首次入库',condition:'冰箱里至少保存过 1 种食材',unit:'种食材',value:foodTypes,thresholds:[1,2,3,5,8,12,20,30]},{icon:'🥗',name:'食材多样家',condition:'冰箱中不同食材的种类数',unit:'种食材',value:foodTypes,thresholds:[1,3,5,10,20,30,50,100]},{icon:'📔',name:'饮食记录员',condition:'有饮食记录的天数',unit:'天',value:days,thresholds:[1,3,7,14,30,60,100,365]},{icon:'👩‍🍳',name:'料理达人',condition:'累计记录的餐食份数',unit:'份餐食',value:meals,thresholds:[1,5,10,25,50,100,250,500]},{icon:'🤝',name:'共享食材',condition:'成功发布共享食材的次数',unit:'次共享',value:shareCount,thresholds:[1,2,5,10,20,50,100,200]}];const levels=achievements.map(item=>item.thresholds.filter(threshold=>item.value>=threshold).length),totalLevels=levels.reduce((sum,level)=>sum+level,0);$('achievement-summary').textContent=`奖牌等级 ${totalLevels}/40`;$('achievement-list').innerHTML=achievements.map((item,index)=>{const level=levels[index],palette=rankColors[Math.max(0,level-1)],nextThreshold=item.thresholds[level],progress=level===8?'满级':`${item.value}/${nextThreshold}`;return `<button type="button" class="achievement-card ${level?'earned':'unearned'}" data-achievement-index="${index}" aria-label="查看${item.name}成就条件"><div class="achievement-medal" style="--medal:${palette[0]};--ribbon:${palette[1]}"><div class="achievement-coin">${item.name}</div></div><div class="achievement-progress">${progress}</div></button>`}).join('');$('achievement-list').querySelectorAll('[data-achievement-index]').forEach(card=>card.addEventListener('click',()=>{const item=achievements[Number(card.dataset.achievementIndex)],level=levels[Number(card.dataset.achievementIndex)],rows=item.thresholds.map((threshold,index)=>{const done=item.value>=threshold,status=done?'已解锁':`还差 ${threshold-item.value} ${item.unit}`;return `<div class="achievement-condition-row"><span class="achievement-condition-rank" style="color:${rankColors[index][1]}">${rankNames[index]}奖牌</span><span>${threshold} ${item.unit}</span><span class="achievement-condition-status ${done?'done':''}">${status}</span></div>`}).join('');$('sheet-title').textContent=`${item.icon} ${item.name} · ${level}/8 级`;$('sheet-body').innerHTML=`<p class="helper">${item.condition}，达到对应数量即可逐级升级：</p>${rows}`;$('recipe-overlay').classList.add('open')}))}
    function renderDietSummary(){const view=currentDietDate(),log=dietLogFor(view),t=getDietTargets(),total=dietTotals(log);$('diet-meals').innerHTML=log.meals.length?log.meals.map(m=>`<div class="menu-dish"><strong>${escapeHtml(m.emoji||'🍽️')} ${escapeHtml(m.name||'菜品')}</strong><div>${Math.round(Number(m.kcal)||0)} 千卡 · 碳水 ${Math.round(Number(m.carbs)||0)}g · 蛋白 ${Math.round(Number(m.protein)||0)}g · 脂肪 ${Math.round(Number(m.fat)||0)}g</div></div>`).join(''):'<p class="helper">这一天还没有记录。</p>';$('diet-kcal').textContent=total.kcal;$('diet-macros').innerHTML=`<div style="display:flex;justify-content:space-around;gap:8px;padding:4px 0">${macroRing('碳水',total.carbs,t.carbs,'#286548')}${macroRing('蛋白质',total.protein,t.protein,'#3b82c4')}${macroRing('脂肪',total.fat,t.fat,'#dd8a45')}</div>`;$('diet-advice').innerHTML=dietAdvice(log);renderPeriodSummary(view);renderDietCalendar();renderAchievements()}

    let adviceRecipeList=[];
    function dietAdvice(log){const t=getDietTargets(),total=dietTotals(log),logged=new Set(log.meals.map(m=>m.id)),dims=[['碳水','carbs'],['蛋白质','protein'],['脂肪','fat'],['热量','kcal']];let h='';dims.forEach(([label,key])=>{const need=t[key]-total[key],unit=key==='kcal'?'千卡':'克';if(need<=0){h+=`<div class="calorie-box" style="margin-top:8px"><span>${label}</span><span class="match" style="color:var(--green)">已达标</span></div>`;return}const recs=recipes.filter(r=>!logged.has(r.id)).map(r=>({r,v:key==='kcal'?recipeTotalKcal(r,1):recipeMacros(r,1)[key]})).sort((a,b)=>b.v-a.v).slice(0,2);h+=`<div class="calorie-box" style="margin-top:8px"><span>${label}还差约 ${Math.round(need)} ${unit}</span><span class="match" style="color:#c07b3a">优先补充</span></div><p class="helper" style="margin:6px 2px 0">${recs.length?recs.map(x=>`<button type="button" class="subchip" data-advice-recipe="${x.r.id}">${x.r.emoji} ${x.r.name}</button>`).join(''):'暂无合适推荐'}</p>`});return h}
    function purchaseAndCookRecipes(list,people){if(!list.length)return;const mult=people/2,needs=new Map();list.forEach(r=>r.ingredients.forEach(([name,grams])=>needs.set(name,(needs.get(name)||0)+Math.round(grams*mult))));const now=Date.now();[...needs.entries()].forEach(([name,need],idx)=>{const have=inventory.filter(x=>x.name===name).reduce((s,x)=>s+Number(x.weight),0);if(have<need)inventory.unshift({name,weight:need-have,unit:'g',expiry:getShelfGuide(name).days,added:now+idx})});needs.forEach((need,name)=>{let remaining=need;for(const item of inventory.filter(x=>x.name===name)){const take=Math.min(Number(item.weight),remaining);item.weight-=take;remaining-=take;if(remaining<=0)break}});inventory=inventory.filter(x=>x.weight>0.001);save();list.forEach(r=>recordMeal(r,mult));renderInventory();renderRecent();renderFoodOptions($('food-select').value);renderDietSummary();toast('已加入冰箱并记入今日饮食记录')}

    function purchaseAndCookSingle(recipe,mult){const now=Date.now();recipe.ingredients.forEach(([name,grams],idx)=>{const need=Math.round(grams*mult),have=inventory.filter(x=>x.name===name).reduce((s,x)=>s+Number(x.weight),0);if(have<need)inventory.unshift({name,weight:need-have,unit:'g',expiry:getShelfGuide(name).days,added:now+idx})});recipe.ingredients.forEach(([name,grams])=>{let remaining=Math.round(grams*mult);for(const item of inventory.filter(x=>x.name===name)){const take=Math.min(Number(item.weight),remaining);item.weight-=take;remaining-=take;if(remaining<=0)break}inventory=inventory.filter(x=>x.weight>0)});save();recordMeal(recipe,mult);renderInventory();renderRecent();$('recipe-overlay').classList.remove('open');showView('inventory');toast('已购买缺料并记入今日饮食记录')}

    function renderRecipePurchase(r,mult){const body=$('sheet-body'),shortages=r.ingredients.map(([name,grams])=>{const need=Math.round(grams*mult),have=inventory.filter(x=>x.name===name).reduce((s,x)=>s+Number(x.weight),0);return {name,shortage:Math.max(0,need-have)}}).filter(x=>x.shortage>0),rows=shortages.map(({name,shortage})=>{const pieceGrams=foodPieceGrams[name],unit=pieceGrams?'piece':'g',amount=pieceGrams?Math.ceil(shortage/pieceGrams):Math.ceil(shortage),options=[['g','克'],['kg','千克'],...(pieceGrams?[['piece','个']]:[])].map(([value,label])=>`<option value="${value}" ${unit===value?'selected':''}>${label}</option>`).join('');return `<div class="purchase-line" data-name="${name}" data-shortage="${shortage}" data-unit="${unit}"><strong>${getFood(name).emoji} ${name}</strong><span class="purchase-need">至少还需 ${foodAmountText(name,shortage,false)}</span><div class="unit-input"><input class="field purchase-amount" type="number" min="0.001" step="${unit==='piece'?'1':'any'}" value="${amount}" inputmode="${unit==='piece'?'numeric':'decimal'}"><select class="unit-select purchase-unit" aria-label="${name}购买单位">${options}</select></div></div>`}).join('');body.innerHTML=`<div class="purchase-form"><h3>填写实际购买量</h3><p>这次缺的食材，请填写实际购买量；确认后先登记购买量，再扣除这道菜所需，剩余量留在冰箱。</p>${rows}<div class="purchase-actions"><button type="button" class="secondary" id="recipe-cancel-purchase">返回</button><button type="button" class="primary" id="recipe-confirm-purchase">加入冰箱并扣除用量</button></div><div class="purchase-validation" id="recipe-purchase-validation"></div></div>`;const update=()=>{const entries=[...body.querySelectorAll('.purchase-line')].map(row=>({amount:Number(row.querySelector('.purchase-amount').value)||0,unit:row.querySelector('.purchase-unit').value,grams:(Number(row.querySelector('.purchase-amount').value)||0)*gramsPerUnit(row.querySelector('.purchase-unit').value,row.dataset.name),shortage:Number(row.dataset.shortage)})),invalid=entries.some(item=>item.grams+0.001<item.shortage||item.grams<=0||(item.unit==='piece'&&!Number.isInteger(item.amount)));$('recipe-confirm-purchase').disabled=invalid;$('recipe-purchase-validation').textContent=invalid?'购买量需要至少覆盖缺少量；按“个”购买请填写整数。':''};body.querySelectorAll('.purchase-line').forEach(row=>{const input=row.querySelector('.purchase-amount'),unit=row.querySelector('.purchase-unit');input.addEventListener('input',update);unit.addEventListener('change',()=>{const grams=(Number(input.value)||0)*gramsPerUnit(row.dataset.unit,row.dataset.name),next=unit.value;row.dataset.unit=next;input.step=next==='piece'?'1':'any';input.inputMode=next==='piece'?'numeric':'decimal';input.value=grams?String(next==='kg'?Number((grams/1000).toFixed(3)):next==='piece'?Math.ceil(grams/gramsPerUnit(next,row.dataset.name)):Math.ceil(grams)):'';update()})});$('recipe-cancel-purchase').addEventListener('click',()=>openRecipe(r.id));$('recipe-confirm-purchase').addEventListener('click',()=>completeRecipePurchase(r,mult));update()}
