    async function loadNearbyShares(){if(!shareClient){toast('共享服务尚未配置');return}if(!nearbyPosition){toast('请先定位查看附近');return}const latDelta=NEARBY_RADIUS_KM/111.32,lonDelta=NEARBY_RADIUS_KM/(111.32*Math.max(.01,Math.cos(nearbyPosition.lat*Math.PI/180))),{data,error}=await shareClient.from('food_shares').select('id,food_name,quantity,unit,expires_at,note,latitude,longitude,created_at').eq('status','open').gt('expires_at',new Date().toISOString()).gte('latitude',Math.max(-90,nearbyPosition.lat-latDelta)).lte('latitude',Math.min(90,nearbyPosition.lat+latDelta)).gte('longitude',Math.max(-180,nearbyPosition.lng-lonDelta)).lte('longitude',Math.min(180,nearbyPosition.lng+lonDelta)).limit(500);if(error){toast('读取共享信息失败，请确认数据库迁移已运行');return}shareRows=(data||[]).map(row=>({...row,distance:distanceKm(nearbyPosition.lat,nearbyPosition.lng,row.latitude,row.longitude)})).filter(row=>row.distance<=NEARBY_RADIUS_KM).sort((a,b)=>a.distance-b.distance);renderNearbyShares();}
    function renderNearbyShares(){const list=$('share-list');shareMarkers.forEach(marker=>marker.remove());shareMarkers=[];if(nearbyMap)shareRows.forEach(row=>{const marker=L.marker([row.latitude,row.longitude]).addTo(nearbyMap).bindPopup(`<strong>${escapeHtml(row.food_name)}</strong><br>${escapeHtml(row.quantity)} ${escapeHtml(row.unit)} · ${escapeHtml(new Date(row.expires_at).toLocaleDateString())}<br>${escapeHtml(row.note||'附近自取')}`);shareMarkers.push(marker)});list.innerHTML=shareRows.length?shareRows.map(row=>{const owned=myShareRows.some(own=>own.id===row.id);return `<article class="food-row"><div class="food-emoji">🥬</div><div class="food-info"><div class="food-name">${escapeHtml(row.food_name)} · ${escapeHtml(row.quantity)} ${escapeHtml(row.unit)}</div><div class="food-meta">约 ${Math.round(row.distance*10)/10} 公里 · ${escapeHtml(row.note||'附近自取')}</div></div><div class="nearby-share-actions"><button class="secondary" type="button" data-share-map="${escapeHtml(row.id)}">地图</button>${owned?'<span class="nearby-share-status">你发布的</span>':`<button class="secondary" type="button" data-claim-share="${escapeHtml(row.id)}" ${nearbyUserId?'':'disabled'}>我要领取</button>`}</div></article>`}).join(''):'<div class="empty">10 公里内暂时没有可领取的食材</div>';list.querySelectorAll('[data-share-map]').forEach(button=>button.addEventListener('click',()=>{const row=shareRows.find(item=>item.id===button.dataset.shareMap);if(row&&nearbyMap){nearbyMap.setView([row.latitude,row.longitude],15);const marker=shareMarkers.find(m=>{const p=m.getLatLng();return p.lat===row.latitude&&p.lng===row.longitude});marker?.openPopup()}}));list.querySelectorAll('[data-claim-share]').forEach(button=>button.addEventListener('click',()=>claimFoodShare(button.dataset.claimShare)));}
    function distanceKm(lat1,lon1,lat2,lon2){const r=Math.PI/180,dLat=(lat2-lat1)*r,dLon=(lon2-lon1)*r,a=Math.sin(dLat/2)**2+Math.cos(lat1*r)*Math.cos(lat2*r)*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}
    async function loadMyShares(){const list=$('my-share-list');if(!shareClient||!nearbyUserId){list.innerHTML='<div class="empty">连接共享服务后显示你发布的食材</div>';return}const {data,error}=await shareClient.from('food_shares').select('id,food_name,quantity,unit,expires_at,note,status,closed_reason,created_at').eq('owner_id',nearbyUserId).order('created_at',{ascending:false}).limit(100);if(error){list.innerHTML='<div class="empty">读取发布记录失败，请先运行附近共享数据库更新 SQL</div>';return}myShareRows=data||[];reconcileShareReservations(myShareRows);renderMyShares();renderNearbyShares()}
    function renderMyShares(){
      const list=$('my-share-list');if(!myShareRows.length){list.innerHTML='<div class="empty">你还没有发布共享食材</div>';return}
      list.innerHTML=myShareRows.map(row=>{
        const expired=new Date(row.expires_at)<=new Date(),canWithdraw=row.status==='open',open=canWithdraw&&!expired,status=open?'共享中':row.status==='closed'?(row.closed_reason==='claimed'?'已领取':'已撤下'):'已过期';
        const actions=open?`<div class="nearby-share-actions"><button class="secondary" type="button" data-close-share="${escapeHtml(row.id)}" data-close-reason="claimed">已领取</button><button class="secondary" type="button" data-close-share="${escapeHtml(row.id)}" data-close-reason="withdrawn">撤下</button></div>`:canWithdraw?`<div class="nearby-share-actions"><button class="secondary" type="button" data-close-share="${escapeHtml(row.id)}" data-close-reason="withdrawn">撤下并返还库存</button></div>`:`<span class="nearby-share-status">${status}</span>`;
        return `<article class="food-row"><div class="food-emoji">${row.closed_reason==='claimed'?'🤝':'🥬'}</div><div class="food-info"><div class="food-name">${escapeHtml(row.food_name)} · ${escapeHtml(row.quantity)} ${escapeHtml(row.unit)}</div><div class="food-meta">${status} · 到期 ${escapeHtml(new Date(row.expires_at).toLocaleDateString())}${row.note?` · ${escapeHtml(row.note)}`:''}</div></div>${actions}</article>`
      }).join('');
      list.querySelectorAll('[data-close-share]').forEach(button=>button.addEventListener('click',()=>closeOwnShare(button.dataset.closeShare,button.dataset.closeReason)));
    }
    async function refreshShareAchievementCount(){if(!shareClient||!nearbyUserId)return;const {count,error}=await shareClient.from('food_shares').select('id',{count:'exact',head:true}).eq('owner_id',nearbyUserId);if(error)return;nearbyShareCount=count||0;renderAchievements()}
    async function closeOwnShare(id,reason){const claimed=reason==='claimed';if(!confirm(claimed?'确认将这份食材标记为已领取？':'确认撤下这份共享食材？'))return;const {data,error}=await shareClient.from('food_shares').update({status:'closed',closed_reason:reason}).eq('id',id).eq('owner_id',nearbyUserId).eq('status','open').select('id').maybeSingle();if(error||!data){toast('这条共享已被处理，或更新失败');await refreshNearbyShares();return}toast(claimed?'已标记为领取完成':'已撤下共享');await refreshNearbyShares()}
    async function claimFoodShare(id){const row=shareRows.find(item=>item.id===id);if(!row||!nearbyUserId)return;if(!confirm(`领取「${row.food_name}」后，这条共享会立即从可领取列表中移除。请先确认取货说明：${row.note||'附近自取'}`))return;const {data,error}=await shareClient.rpc('claim_food_share',{p_share_id:id});if(error){toast('领取失败，请确认数据库更新 SQL 已运行');return}if(!data){toast('这份食材已被领取或撤下');await refreshNearbyShares();return}toast('已领取，请按取货说明完成交接');await refreshNearbyShares()}
    let sharePublishing=false;
    async function publishFoodShare(){
      const button=$('publish-share');if(sharePublishing)return;sharePublishing=true;if(button)button.disabled=true;
      let reservationId=null;
      try{
        if(!shareClient||!nearbyUserId){toast('共享服务尚未连接，请稍后再试');return}
        if(!nearbyPosition){toast('请先点击定位并查看附近');return}
        if(!$('share-consent').checked){toast('请先确认共享信息和模糊位置');return}
        const entry=$('share-item')._shareItems?.[Number($('share-item').value)];if(!entry){toast('没有可分享的临期食品');return}
        const qty=Number($('share-quantity').value),unit=$('share-unit').value,max=unit==='piece'?Math.floor(entry.weight/foodPieceGrams[entry.name]):Math.floor(entry.weight);
        if(!(qty>0&&qty<=max)){toast('分享数量超过当前库存');return}
        reservationId=window.crypto?.randomUUID?window.crypto.randomUUID():([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16));
        if(!reserveShareInventory(entry,qty,unit,reservationId)){reservationId=null;toast('库存已变化，请刷新后重新选择');return}
        const coords=obscureCoords(nearbyPosition.lat,nearbyPosition.lng),expires=new Date();expires.setDate(expires.getDate()+remainingDays(entry));expires.setHours(23,59,59,999);
        const {error}=await shareClient.from('food_shares').insert({id:reservationId,food_name:entry.name,quantity:qty,unit,expires_at:expires.toISOString(),note:$('share-note').value.trim(),latitude:coords.lat,longitude:coords.lng});
        if(error){restoreShareReservation(reservationId);reservationId=null;toast('发布失败，已将预留食材放回冰箱；请确认数据库表和权限已配置');return}
        $('share-note').value='';$('share-consent').checked=false;toast('已发布并从冰箱库存中预留');await refreshShareAchievementCount();await refreshNearbyShares();
      }catch(error){if(reservationId)restoreShareReservation(reservationId);toast('发布失败，已将预留食材放回冰箱')}
      finally{sharePublishing=false;if(button)button.disabled=false}
    }
