      let swipeStart=null,suppressRecentClick=false;const attachSwipe=el=>{el.addEventListener('pointerdown',e=>{const shell=e.target.closest('.recent-shell');if(!shell||e.target.closest('.delete-item,.share-item-action'))return;swipeStart={shell,x:e.clientX,y:e.clientY}});el.addEventListener('pointerup',e=>{if(!swipeStart)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;if(Math.abs(dx)>Math.abs(dy)&&Math.abs(dx)>35){swipeStart.shell.classList.toggle('swiped',dx<0);swipeStart.shell.classList.toggle('share-swiped',dx>0);suppressRecentClick=true;setTimeout(()=>suppressRecentClick=false,350)}swipeStart=null});el.addEventListener('pointercancel',()=>swipeStart=null);el.addEventListener('click',e=>{if(suppressRecentClick){e.preventDefault();return}const shell=e.target.closest('.recent-shell');if(!shell)return;if(e.target.closest('.delete-item')){const entry=Number(shell.dataset.entry);inventory=inventory.filter(x=>Number(x.added)!==entry);save();renderInventory();renderRecent();toast('食材已删除');return}const share=e.target.closest('.share-item-action');if(share){openShareFromInventory(share.dataset.shareEntry);return}if(!e.target.closest('button')){shell.classList.remove('swiped','share-swiped')}})};attachSwipe($('recent-list'));attachSwipe($('inventory-list'));
